sksl:
uniform shader image;
uniform shader blurred;
uniform float2 size;
uniform float time;
uniform float blur;
uniform float amount;
uniform float bloom;
uniform float softContrast;
layout(color) uniform half4 glowTint;
uniform float tintAmount;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
float luma(float3 c) {
    return dot(c, float3(0.2126, 0.7152, 0.0722));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float4 b = float4(blurred.eval(coord));
    float3 bs = unp(b);
    bs = (bs - 0.5) * softContrast + 0.5;
    bs = mix(bs, bs * float3(glowTint.rgb) * 1.4, tintAmount);
    float3 soft = mix(s, bs, amount);
    float3 o = 1.0 - (1.0 - soft) * (1.0 - bs * bloom * luma(bs));
    return fin(c, float4(saturate(o) * c.a, c.a), opacity);
}
